            { label: "Ferritin", value: r.ferritin?.value, unit: "ng/mL", tone: labTone(r.ferritin?.status), missing: !r.ferritin },
            { label: "TSAT", value: r.tsat?.value, unit: "%", tone: labTone(r.tsat?.status), missing: !r.tsat },
